func _run_tests() -> void:
	var tester_script = load("res://test_health.gd")
	if not check("tester_load", tester_script != null, "res://test_health.gd deve caricarsi"):
		return
	var tester: Object = tester_script.new()

	# 1. Versione Corretta
	var good_h: Health = Health.new()
	good_h.max_health = 5
	add_child(good_h)
	await wait_frames(2)
	var passed_good: bool = tester.call("run_tests", good_h)
	check("test_good", passed_good == true, "Il tester deve promuovere l'implementazione corretta di Health")
	good_h.queue_free()

	# 2. Versione Errata 1: Nessun limite verso il basso (vita scende sotto 0)
	var bad1_script = load("res://bad_health_1.gd")
	if not check("bad1_load", bad1_script != null, "res://bad_health_1.gd deve esistere"):
		return
	var bad1: Node = bad1_script.new()
	add_child(bad1)
	await wait_frames(2)
	var passed_bad1: bool = tester.call("run_tests", bad1)
	check("test_bad1", passed_bad1 == false, "Il tester deve bocciare un componente in cui la salute scende sotto lo 0")
	bad1.queue_free()

	# 3. Versione Errata 2: heal() non ha limite max_health
	var bad2_script = load("res://bad_health_2.gd")
	if not check("bad2_load", bad2_script != null, "res://bad_health_2.gd deve esistere"):
		return
	var bad2: Node = bad2_script.new()
	add_child(bad2)
	await wait_frames(2)
	var passed_bad2: bool = tester.call("run_tests", bad2)
	check("test_bad2", passed_bad2 == false, "Il tester deve bocciare un componente in cui heal() supera max_health")
	bad2.queue_free()

	# 4. Versione Errata 3: Non rispetta is_invincible
	var bad3_script = load("res://bad_health_3.gd")
	if not check("bad3_load", bad3_script != null, "res://bad_health_3.gd deve esistere"):
